import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory tos, uint[] memory v) public {
        vm.assume(tos.length > 0);
        vm.assume(tos.length == v.length);
        vm.assume(caddress != address(c)); // avoid self-call interference

        bool ret;
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, tos, v));
        if (success) {
            ret = abi.decode(data, (bool));
        } else {
            // if it reverts, we cannot check the return value; skip
            vm.assume(false);
        }

        assertTrue(ret, "transfer should return true when it does not revert");
    }
}

