pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == v.length);
        bool success;
        if (_tos.length > 0) {
            (success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        } else {
            (success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        }
        // The contract has no public storage variable. The reference implementation should not revert for non-empty arrays.
        // For empty _tos, the reference reverts; for non-empty, it returns true.
        // Here we assert that the call does not revert when _tos.length > 0.
        assertTrue(_tos.length == 0 || success);
    }
}
